public void processOperation(MZNAG_CustomerStatusBatchContract _contract)
{
    SalesTable salesTable;
    CustAccount custAccount = _contract.parmCustAccount();

    ttsbegin;

    while select forUpdate salesTable
        where salesTable.CustAccount == custAccount
           && salesTable.CustomerStatus == MZNAG_CustomerStatus::NotProcessed
    {
        salesTable.CustomerStatus = MZNAG_CustomerStatus::Processed;
        salesTable.update();
    }

    ttscommit;
}
